parameters.jsonBody:
={{
(() => {
  const text = ($json.parsed_text || '').slice(0, 4000);

  return {
    // Kleines Modell: Verschlagwortung ist Metadaten-Arbeit, keine Fachantwort.
    // Gemessen 25.08.: 50 s mit dem grossen Modell - und eine Chat-Antwort
    // wartete solange in derselben Warteschlange.
    model: 'gemma4:e2b',
    keep_alive: '24h',
    stream: false,
    options: {
      temperature: 0
    },
    format: {
      type: 'object',
      properties: {
        document_type: { type: 'string' },
        language: { type: 'string' },
        domain: { type: 'string' },
        subdomain: { type: 'string' },
        methods: {
          type: 'array',
          items: { type: 'string' }
        },
        keywords: {
          type: 'array',
          items: { type: 'string' }
        },
        tags: {
          type: 'array',
          items: { type: 'string' }
        },
        summary: { type: 'string' }
      },
      required: [
        'document_type',
        'language',
        'domain',
        'subdomain',
        'methods',
        'keywords',
        'tags',
        'summary'
      ]
    },
    messages: [
      {
        role: 'system',
        content: 'You are a document tagging assistant for heterogeneous production engineering documents. Return JSON only. Create document-dependent metadata and concise technical tags. RULES: (1) keywords, tags, methods and summary MUST be written in the language of the document (German document -> German terms; never translate German documents into English). (2) document_type is English and one of: Dissertation, Master thesis, Bachelor thesis, Project work, Research report, Standard/Guideline, Regulation/Law, Exam catalogue, Training material, Textbook, Manual/Guide, Datasheet, Presentation, Test report/Protocol, Article, Invoice, Reminder/Dunning notice, Quotation/Offer, Request for quotation, Purchase order, Order confirmation, Delivery note, Cover letter, Expense report, Routing slip, Contract/Agreement, Non-disclosure agreement, Other. (2a) The collection is MIXED: next to academic and technical documents it holds the business paperwork of a contract laboratory (invoices, offers, orders, letters, routing slips, expense reports). Pick the type the document ACTUALLY is. (2b) If nothing on the list clearly fits, answer "Other". An honest "Other" is correct; a type that only roughly fits is wrong and cannot be corrected later. Never force a document into a neighbouring type. (2c) A business document is NOT a Datasheet, Test report/Protocol, Article or Standard/Guideline just because it carries numbers, prices, a table, a reference number or a letterhead. (3) language is the ISO name in English (German, English). (4) summary: 2-3 sentences, what the document is for and what it covers.'
      },
      {
        role: 'user',
        content:
          'Analyze the following document and return structured metadata.\n\n' +
          'Filename: ' + ($json.filename || '') + '\n' +
          'Mime-Type: ' + ($json.mime_type || '') + '\n\n' +
          'Return these fields:\n' +
          '- document_type\n' +
          '- language\n' +
          '- domain\n' +
          '- subdomain\n' +
          '- methods\n' +
          '- keywords\n' +
          '- tags\n' +
          '- summary\n\n' +
          'Document text:\n' +
          text
      }
    ]
  };
})()
}}

parameters.jsCode:
// ⚠ NICHT $input.all(): "Grafikkarte freigeben" direkt davor laeuft EINMAL
//   (executeOnce) und gibt genau EIN Element weiter. Damit schrumpfte jeder
//   Durchgang auf ein einziges Dokument - die uebrigen blieben stumm in
//   input/ liegen und wurden beim naechsten Durchgang erneut komplett durch
//   Docling gejagt (gemessen 24.08.: 10 -> 9 -> 8 ... ein Dokument je Lauf,
//   vier grosse Arbeiten siebenmal konvertiert, bis die Claim-Garantie sie
//   nach drei Stunden aussortierte). Massgeblich ist die Liste der
//   KONVERTIERTEN Dokumente: ein Element je Datei, in Reihenfolge; die
//   Herkunft (Name, Ordner) steht in derselben Reihenfolge bei
//   "Dateien klassifizieren".
const _roh = $('Dateien in JSON umwandeln').all();
const _quellen = $('Dateien klassifizieren').all();
const karte = ($('Bereichskarte bauen').first().json.karte) || {};

// ⛔ Ein Durchgang, der nichts ablegt, darf das nicht verschweigen.
//   Gemessen 22./23.09.: Gab die Unterkette nichts zurueck, lieferte
//   dieser Baustein still `return []`. Der Durchgang endete GRUEN und
//   leer, jede Minute neu. Das hat zwei Tage gekostet - nicht weil es
//   kaputt war, sondern weil es still war.
//
// ⭐ Bewusst KEIN Wurf. Ein Wurf beendet den Durchgang vor
//   "Sperre freigeben"; die Laufsperre bliebe liegen und blockierte
//   alles bis zum 120-Minuten-Notnagel - genau das ist am 04.08. schon
//   einmal passiert. Also: melden und weitermachen wie bisher.
//
// ⚠ Hoerbar ist die Zeile nur mit CODE_ENABLE_STDOUT=true in der
//   Compose. Ohne den Schalter landet sie in der Browser-Konsole.
// --- STILLE MELDEN ---
const _stille_melden = (roh, quellen, melden) => {
  if (quellen.length && roh.length !== quellen.length) {
    melden('[LEERLAUF] Unterkette lieferte ' + roh.length +
           ' Ergebnis(se) fuer ' + quellen.length + ' Datei(en) - dieser ' +
           'Durchgang legt nichts ab, der Eingang bleibt voll, und er ' +
           'meldet trotzdem Erfolg. Siehe BUGS_UND_FIXES 29.');
    return true;
  }
  return false;
};
// --- ENDE STILLE MELDEN ---
_stille_melden(_roh, _quellen, (m) => console.error(m));

// ⭐ PAARUNG PER DATEINAME (26.08.): Die Unterkette gibt je Datei ein
//   Element mit `docling_filename` zurueck. Faellt eine Datei dort aus
//   (kein passender Zweig, Fehler), verschiebt sich sonst die Position -
//   gemessen 26.08.: die Pruefungs-Excel im Bereich AuW bekam den Text des
//   Testfragen-PDFs. Ohne Namen bleibt die Position der Rueckfall.
const _nameVon = (q) => ((q.binary && q.binary.data && q.binary.data.fileName) || (q.json && q.json.fileName) || '');
const _ausgabe = _roh.map((rohItem, index) => {
  const _rohName = (rohItem && rohItem.json && (rohItem.json.docling_filename || rohItem.json.dateiname)) || '';
  const sourceItem = (_rohName && _quellen.find(q => _nameVon(q) === _rohName)) || _quellen[index] || {};
  const fileBinary = (sourceItem.binary && sourceItem.binary.data) || {};

  const fileName = fileBinary.fileName
    || (sourceItem.json && sourceItem.json.fileName)
    || `document_${index + 1}.pdf`;
  const directory = fileBinary.directory || '/files/dokumente';
  const mimeType = fileBinary.mimeType || 'application/pdf';
  // ⚠ NICHT vom Eingang lesen. Zwischen "Dateien in JSON umwandeln" und
  //   hier steht "Grafikkarte freigeben" - ein HTTP-Baustein, dessen
  //   Antwort {"status":"ok"} den Datensatz ERSETZT. Frueher gingen so
  //   viel Rechenzeit verloren; das Dokument
  //   landete mit "rohtext fehlt oder ist leer" in aussortiert.
  const parsedText = (rohItem && rohItem.json && rohItem.json.data) || '';

  // Der Arbeitsbereich steckt im Pfad, nicht in einer Einstellung:
  //   /files/dokumente/<bereich>/input  ->  <bereich>
  // Damit landet ein Dokument dort, wo es hingelegt wurde - und nicht in
  // einem fest eingestellten Bereich, wie frueher
  const teile = String(directory).split('/').filter(Boolean);
  // Unterordner im Eingang = Kategorie-Vorgabe (entschieden 27.08.):
  //   /files/dokumente/<bereich>/input/Normen/x.pdf -> Bereich <bereich>, Vorgabe "Normen"
  //   /files/dokumente/<bereich>/input/Normen/Kleben/x.pdf -> Vorgabe "Normen", Themen "Kleben"
  let zustand = teile[teile.length - 1] || '';
  let bereich = teile[teile.length - 2] || '';
  let kategorie_vorgabe = '';
  let themen_vorgabe = '';
  const iInput = teile.lastIndexOf('input');
  if (iInput >= 1 && iInput < teile.length - 1) {
    // Datei liegt in einem Unterordner (beliebig tief) von input/
    bereich = teile[iInput - 1] || '';
    zustand = 'input';
    kategorie_vorgabe = teile[iInput + 1] || '';
    themen_vorgabe = teile.slice(iInput + 2).join(' / ');
  }
  const wurzel = `/files/dokumente/${bereich}`;
  // ⭐ Der Pfad unterhalb des Eingangs. Archiv und Aussortiert spiegeln ihn,
  //   sonst passten zwei gleichnamige Dateien nicht nebeneinander - genau
  //   daran ging die Kundenzuordnung verloren (BUGS_UND_FIXES.md 6).
  const _seg = String(directory).split('/').filter(Boolean);
  const _iIn = _seg.lastIndexOf('input');
  const unter = (_iIn >= 0 ? _seg.slice(_iIn + 1) : []).concat([fileName]).join('/');

  return {
    json: {
      filename: fileName,
      source_path: `${directory}/${fileName}`,
      directory: directory,
      bereich: bereich,
      zustand: zustand,
      // Kein Rueckfall auf den Bereichsnamen: Der Ordner in
      // AnythingLLM heisst unter Umstaenden anders benannt. Wer hier
      // raet, legt den Bestand eines Bereichs in zwei Ordner ab.
      ablage: karte[bereich],
      unterpfad: unter,
      schluessel: null,
      abdruck: null,
      // ⭐ Die Office-Regel, gerechnet vom mkmd-Dienst (belegquelle.py):
      //   nur_beleg=true heisst, dass neben dieser PDF das gleichnamige
      //   Word-/PowerPoint-Original liegt. Dann ist SIE kein Dokument,
      //   sondern nur dessen Seitenquelle - sie traegt den Schluessel des
      //   Originals, und hochgeladen wird sie nicht.
      nur_beleg: false,
      traeger: '',
      hochladen: true,
      archiv_path: `${wurzel}/archiv/${unter}`,
      aussortiert_path: `${wurzel}/aussortiert/${unter}`,
      aussortiert_log: `${wurzel}/aussortiert/aussortiert.log`,
      // ⛔ Die Vormerkliste gehoert in den BEREICH, nicht neben das Dokument.
      //   "Ablage entscheiden" rechnete sie bis zum 24.09. als
      //   dirname(dirname(ziel)) aus - das trifft den Bereich nur bei einer
      //   FLACH abgelegten Datei. Bei <bereich>/archiv/Normen/x.pdf kam
      //   <bereich>/archiv heraus, bei <bereich>/archiv/A/B/x.pdf sogar
      //   <bereich>/archiv/A. So entstand je Ordnerebene eine eigene
      //   bilder-nachholen.txt - und pruef_proxy.py:559, das einzige, was die
      //   Liste liest und aufraeumt, kennt nur <bereich>/bilder-nachholen.txt.
      //   Derselbe Fehler wie bei _loesch_wurzel (zweimal dirname).
      vormerk_path: `${wurzel}/bilder-nachholen.txt`,
      mime_type: mimeType,
      kategorie_vorgabe: kategorie_vorgabe,
      themen_vorgabe: themen_vorgabe,
      parsed_text: parsedText,
      text_length: parsedText.length,
      // Grund, falls die Textextraktion scheiterte (Docling-Status), und ob
      // der Zweitversuch ohne Bildbeschreibung lief (-> Vormerkliste).
      fehler: (rohItem && rohItem.json && (rohItem.json.fehler || (rohItem.json.error && (rohItem.json.error.message || rohItem.json.error)))) || '',
      ohne_bilder: !!(rohItem && rohItem.json && rohItem.json.ohne_bilder),
      processed_at: new Date().toISOString()
    }
  };
});

// ⭐ Die Schluessel in EINEM Aufruf vom mkmd-Dienst holen.
//
// ⛔ Der Schluessel wird hier NICHT gerechnet. Er entsteht aus SHA-256, einem
//   Basiswechsel, einer NFKD-Bereinigung und einer Byte-Kuerzung; eine zweite
//   Fassung davon in JavaScript waere genau der Fehler, fuer den der
//   mkmd-Dienst gebaut wurde - im Ablaufplan lag frueher eine eigene
//   Nachbildung der Markdown-Erzeugung, sogar in zwei Fassungen, und keine
//   kannte die Seitennummerierung. Eine Rechnung, zwei Leser: Der Proxy ruft
//   schluessel.py direkt auf, n8n ueber diesen Weg.
const _dateien = _ausgabe.map(e => ({ bereich: e.json.bereich,
                                      unterpfad: e.json.unterpfad }));
if (_dateien.length) {
  const _antwort = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://mkmd-dienst:5055/schluessel',
    body: { dateien: _dateien },
    json: true,
    timeout: 30000,
  });
  if ((_antwort.fehler || []).length) {
    // ⛔ Ein Dokument ohne Schluessel darf NICHT hochgeladen werden - es
    //   entstuende ein Bestandseintrag, den die Auswertung nie wiederfindet.
    //   Lieber den Durchgang abbrechen, wie bei "Bestand nicht abfragbar".
    throw new Error('Schluessel nicht berechenbar fuer ' +
                    _antwort.fehler.length + ' Datei(en): ' +
                    (_antwort.fehler[0] || {}).grund);
  }
  const _karte = {};
  for (const e of (_antwort.schluessel || [])) {
    _karte[e.bereich + '\u0000' + e.unterpfad] = e;
  }
  for (const e of _ausgabe) {
    const t = _karte[e.json.bereich + '\u0000' + e.json.unterpfad];
    if (!t) {
      throw new Error('Kein Schluessel fuer eine Datei - Durchgang abgebrochen.');
    }
    e.json.schluessel = t.schluessel;
    e.json.abdruck = t.abdruck;
    e.json.nur_beleg = t.nur_beleg === true;
    e.json.traeger = t.traeger || '';
  }
}

// ⛔ WAS UEBERHAUPT IN DEN KATALOG DARF - und zwar VOR dem Upload.
//   Bis zum 24.09. stand diese Entscheidung erst in "Ablage entscheiden",
//   also HINTER "Upload Markdown an AnythingLLM" und HINTER dem Einbetten.
//   Eine Datei mit unvorgesehener Endung wurde dadurch erst hochgeladen,
//   eingebettet und DANN aussortiert: Die Datei lag danach in aussortiert/,
//   ihr Eintrag stand weiter im Arbeitsbereich - durchsuchbar und zitierbar,
//   ohne dass ihn jemand wieder entfernt. Die Positivliste war eine
//   Ablage-Regel; eine Aufnahme-Regel ist sie erst hier.
//
// ⚠ Diese drei Listen stehen NUR HIER. "Ablage entscheiden" liest die
//   Marken (endung, korrespondenz, nicht_vorgesehen, leer) aus diesem
//   Baustein - zwei Fassungen derselben Liste laufen sonst auseinander.
//
//    MINDESTZEICHEN ist bewusst niedrig: Es geht um "gar nichts extrahiert",
//    nicht um eine Qualitaetsbewertung. Ein Deckblatt mit zwei Zeilen ist ein
//    gueltiges Dokument.
const MINDESTZEICHEN = 20;

// ⭐ DIE LISTEN KOMMEN AUS "NUR EIN BEREICH JE DURCHGANG" (05.10.).
//
// ⛔ Sie standen bis heute HIER - und damit zu spaet. Gebraucht werden sie
//   schon VOR der Sperre: Eine Charge aus lauter Dateien mit unvorgesehener
//   Endung (gemessen 85 von 247 Durchgaengen) macht "Nur Dokumente
//   hochladen" leer, die Schleife laeuft nicht an, "Sperre freigeben" wird
//   nie erreicht - und die Sperre bleibt bis zum 120-Minuten-Notnagel
//   liegen. Also besitzt der fruehe Baustein die Liste, und dieser hier
//   LIEST sie. Zwei Fassungen derselben Liste laufen auseinander, und es
//   faellt erst auf, wenn eine .jpg im Bestand steht.
// ⚠ Von hier reist sie unveraendert als Text weiter (vorgesehen_liste) -
//   "Ablage entscheiden" braucht sie fuer seine Begruendung.
// ⛔ In try/catch: $('...') WIRFT, wenn der Baustein umbenannt wurde oder
//   in diesem Durchgang nicht gelaufen ist - und ein Wurf hier faellt mit
//   onError "continueRegularOutput" auf den Durchlass zurueck, am Riegel
//   unten vorbei. Der haeufigste Grund fuer "die Liste kam nicht an" waere
//   also genau der gewesen, den der Riegel nicht sieht.
let _listen = {};
try {
  _listen = (($('Nur ein Bereich je Durchgang').first() || {}).json) || {};
} catch (e) {
  console.error('[Aufnahme] ⛔ "Nur ein Bereich je Durchgang" ist nicht '
                + 'abfragbar (' + e.message + ') - umbenannt oder in diesem '
                + 'Durchgang nicht gelaufen.');
}
const VORGESEHEN = _listen.vorgesehen;
const KORRESPONDENZ = _listen.korrespondenz_formate;
// ⛔ Ohne die Listen NICHT weitermachen: Dann waere nichts "nicht
//   vorgesehen", und jede Messgeraetedatei ginge als Dokument in den
//   Bestand - durchsuchbar und zitierfaehig. Lieber abbrechen, wie bei
//   "Bestand nicht abfragbar". (Gemessen am KAP-Bestand gehen 386 Dateien
//   in Formaten, die niemand vorgesehen hat, ungefragt an Tika: 72x .001,
//   34x .tra, 33x .tsx, 32x .inf, 9x .sav ... Aus einer Binaerdatei kommt
//   fast immer irgendein Zeichensalat.)
// ⛔ ABER NICHT WERFEN (05.10.). Hier stand `throw new Error(...)`.
//   Dieser Baustein traegt onError: "continueRegularOutput", und bei
//   continuesOnError reicht n8n die EINGANGSDATEN unveraendert weiter
//   (workflow-execute.js des laufenden 2.31.4). Die Elemente kaemen also
//   OHNE JEDE MARKE bei "Nur Dokumente hochladen" an, und dessen Filter
//   prueft `hochladen !== false` - undefined ist nicht false. Gemessen:
//   4 von 4 unmarkierten Elementen gingen in den Upload. Der Wurf war
//   damit ein DURCHLASS, das Gegenteil dessen, was hier daruebersteht.
// ⛔ onError: "stopWorkflow" ist keine Loesung: Dieser Baustein liegt
//   zwischen "Sperre setzen" und "Sperre freigeben". Ein echter Abbruch
//   liesse die Sperre bis zum 120-Minuten-Notnagel liegen - der Fehler
//   vom 04.08.
// ⭐ Der Riegel faellt deshalb in den DATEN zu, nicht im Kontrollfluss:
//   jedes Element laeuft weiter und keines ist freigegeben. Weiter als bis
//   "Nur Dokumente hochladen" kommt dann keines - "Ablage entscheiden"
//   liest die Elemente nicht aus seinem Eingang, sondern mit $('Code').all(),
//   und sieht sie deshalb trotzdem. Damit die Kette dahinter ueberhaupt
//   eingeplant wird, traegt "Nur Dokumente hochladen" alwaysOutputData;
//   ohne das bliebe die Sperre 120 Minuten liegen. Abschnitt 10 in
//   bau/aufnahmetest.js rechnet es bis "Sperre freigeben" durch.
const _listen_fehlen = !Array.isArray(VORGESEHEN) || !VORGESEHEN.length
                       || !Array.isArray(KORRESPONDENZ);
if (_listen_fehlen) {
  console.error('[Aufnahme] ⛔ Die Positivliste kam nicht aus "Nur ein ' +
                'Bereich je Durchgang" an. Dieser Durchgang laedt NICHTS ' +
                'hoch: ' + _ausgabe.length + ' Datei(en) bleiben liegen und ' +
                'kommen mit demselben Schluessel zurueck, sobald die Listen ' +
                'wieder ankommen.');
}

for (const e of _ausgabe) {
  // Die Endung aus dem Dateinamen - derselbe Name, den auch der
  // Schluessel-Dienst gesehen hat.
  const _t = String(e.json.filename || '').split('.');
  const endung = _t.length > 1 ? _t.pop().toLowerCase() : '';
  e.json.endung = endung;
  e.json.leer = Number(e.json.text_length || 0) < MINDESTZEICHEN;
  e.json.mindestzeichen = MINDESTZEICHEN;
  if (_listen_fehlen) {
    e.json.korrespondenz = false;
    e.json.nicht_vorgesehen = true;      // fail-closed, in den Daten
    // Der WAHRE Grund fuer "Ablage entscheiden". Ohne ihn stuende im
    // aussortiert.log "Format nicht vorgesehen (.pdf)" - und wer das
    // liest, sucht den Fehler in der Datei statt in der Kette.
    e.json.listen_fehlen = true;
    e.json.vorgesehen_liste = '';
    e.json.hochladen = false;
    continue;
  }
  e.json.korrespondenz = KORRESPONDENZ.indexOf(endung) !== -1;
  e.json.nicht_vorgesehen = !e.json.korrespondenz
    && VORGESEHEN.indexOf(endung) === -1;
  e.json.vorgesehen_liste = VORGESEHEN.join(', ');
  // ⭐ Hochgeladen wird nur, was ein eigenes, lesbares Dokument ist.
  //   "Ablage entscheiden" entscheidet daraufhin ueber den Ablageort - es
  //   bekommt jedes Element, auch die hier ausgeschlossenen.
  e.json.hochladen = !e.json.nur_beleg
    && !e.json.korrespondenz && !e.json.nicht_vorgesehen && !e.json.leer;
}
return _ausgabe;

// Aus der Namensliste ein Element je Datei - ohne einen Byte Inhalt.
//
// ⭐ WAS DIESER BAUSTEIN LIEFERT, ist genau das, was "Nur ein Bereich je
//   Durchgang" braucht: Dateiname und Ordner. Vorher kamen beide aus
//   item.binary.data - also aus einer Datei, die dafuer erst vollstaendig
//   gelesen werden musste. Jetzt stehen sie im json, und gelesen wird erst
//   hinter der Sperre, und nur die Charge.
//
// ⛔ WARUM 'muster' NEBEN 'pfad' STEHT. n8n gibt den Dateiwaehler von
//   "Daten vom Server laden" an fast-glob weiter - also an einen
//   MUSTERLESER, nicht an einen Pfad. In 'Angebot (2) [alt].pdf' ist
//   '(2)' eine Gruppe und '[alt]' eine Zeichenklasse; als Muster gelesen
//   findet dieser Pfad die eigene Datei NICHT. Sie fiele lautlos aus dem
//   Durchgang, bliebe im Eingang liegen und wuerde nach
//   KI4KI_CLAIM_MINUTEN aussortiert - ohne dass irgendwo ein Fehler steht.
//   Deshalb wird hier entschaerft. 'pfad' bleibt unentschaerft: er ist
//   der Schluessel, an dem "Angaben wieder anheften" die Angaben
//   wiederfindet, und er steht so auch im Protokoll.
//
// ⛔⛔ ( ) [ ] GEHOEREN NICHT IN DIESE LISTE - n8n entschaerft sie SELBST.
//   Hier stand bis zum 06.10. fast-globs vollstaendige escapePath-Liste.
//   Das war einmal zu viel: "Daten vom Server laden" gibt den
//   Dateiwaehler nicht an fast-glob durch, sondern durch
//   normalizeFileSelector(), und die ruft in n8n 2.31.4
//   (nodes-base .../ReadWriteFile/helpers/utils.js):
//       str = str.replace(/[()[\\]]/g, '\\$&');
//   Aus unserem 'Angebot \\(2\\).pdf' wurde damit 'Angebot
//   \\\\(2\\\\).pdf' - fuer picomatch ein LITERALER Backslash gefolgt
//   von einer Gruppe. Null Treffer. Gemessen am 06.10. im laufenden
//   Container ueber die 300 Pfade des Eingangs: mit den Klammern in
//   dieser Liste 293 Treffer und 7 Nieten, ohne sie 300 Treffer und
//   keine Niete - und alle 7 Nieten waren genau die Pfade mit Klammern.
//   Im Gesamtbestand tragen 451 von 6.798 Dateien (6,6 %) ( ) [ ].
//
// ⚠ DAS HAENGT AN DER n8n-FASSUNG. Faellt escapeSpecialCharacters bei
//   einem Update weg, kippt es zurueck und die Klammern MUESSEN wieder
//   hier hinein. Nicht raten, sondern messen:
//   bau/ablauf_pruefen.py, test_findet_n8n_die_dateien_auch_wirklich -
//   die faehrt die ganze Kette im echten Container und wird bei zu viel
//   wie bei zu wenig Entschaerfung rot.
const roh = String(($input.all()[0] || {}).json
                   && ($input.all()[0].json.stdout || '')) || '';

// find liefert mit -print0 NUL-getrennt. Kommt der Trenner nicht durch,
// tut es der Zeilenumbruch - dann gehen nur Namen MIT Zeilenumbruch
// verloren, statt der ganzen Liste.
const teile = (roh.indexOf('\u0000') !== -1) ? roh.split('\u0000')
                                             : roh.split('\n');

// ⚠ WACHE FUER DIE 10-MB-KAPPE. executeCommand schneidet stdout bei
//   10 MB ab und behaelt das ENDE - abgeschnitten wuerden also die
//   ERSTEN Dateien, und zwar ohne jede Meldung. Am 06.10. mass die
//   Liste 630 KB, 6 % des Deckels; bei zehnfachem Bestand waere sie
//   dran. Ab 5 MB soll es im Protokoll stehen, bevor es still wird.
if (roh.length > 5 * 1024 * 1024) {
  console.log(`[Eingang] ⚠ Die Namensliste misst `
              + `${(roh.length / 1048576).toFixed(1)} MB. executeCommand `
              + `kappt bei 10 MB und behaelt das ENDE - die ersten `
              + `Dateien fielen dann lautlos weg. Eingang verkleinern `
              + `oder die Liste in Haeppchen lesen.`);
}

// fast-globs escapePath fuer POSIX, OHNE ( ) [ ] - die entschaerft n8n
// selbst (siehe oben).
const entschaerfen = (s) => String(s).replace(/[\\$^*+?{}|!@]/g, '\\$&');

const raus = [];
for (const z of teile) {
  // ⚠ NUR Zeilenenden weg, NICHT trim(). trim() haette ein Leerzeichen
  //   am Namensende mit abgeschnitten; der Pfad im json und der Pfad auf
  //   der Platte gingen dann auseinander, und die Datei waere lautlos
  //   nicht gefunden worden. Am 06.10. ist davon keine Datei im Bestand
  //   betroffen - die Zusicherung soll halten, bevor die erste kommt.
  //   Mit -print0 faellt hier ohnehin nichts an; die Zeile deckt den
  //   Rueckfall auf Zeilenumbruch ab (dort haengt ein \r mit dran).
  const pfad = z.replace(/^[\r\n]+|[\r\n]+$/g, '');
  if (!pfad) continue;
  const i = pfad.lastIndexOf('/');
  if (i < 1) continue;            // ohne Ordner kein sicherer Schluessel
  raus.push({ json: {
    pfad: pfad,
    muster: entschaerfen(pfad),
    // Die Namen sind dieselben wie in binary.data - "Nur ein Bereich je
    // Durchgang" liest sie ueber angabe() aus beiden Quellen.
    fileName: pfad.slice(i + 1),
    directory: pfad.slice(0, i),
  } });
}

// ⛔ KEIN stiller Rueckfall auf "nichts". Ein leerer Eingang ist ein
//   normaler Zustand und endet hier mit einer leeren Liste - dann wird
//   "Nur ein Bereich je Durchgang" gar nicht erst eingeplant, "Sperre
//   setzen" ebenso wenig, und es wird auch keine Sperre gesetzt, die
//   niemand freigibt. Genau so lief es vorher auch, als "Daten vom Server
//   laden" bei leerem Eingang nichts lieferte.
console.log(`[Eingang] ${raus.length} Dateien gefunden (nur Namen gelesen, `
            + `keine Inhalte).`);
return raus;

// Die Angaben wieder an die Datei heften.
//
// ⛔ WARUM DAS NOETIG IST: "Daten vom Server laden" ist ein
//   Read/Write-Baustein. Er baut je gefundener Datei ein NEUES Element und
//   fuellt nur dessen binary; das json des Elements, das hineinging, wirft
//   er weg. Ohne diesen Baustein waeren damit alle Marken weg, die "Nur ein
//   Bereich je Durchgang" gesetzt hat - allen voran 'belegquelle'. Folge:
//   Die mitgelieferte PDF neben einem Office-Original liefe wieder durch
//   Docling (293 von 779 PDF im gemessenen Bestand) - der Unterschied
//   zwischen Tagen und Wochen.
//
// ⚠ ZUSAMMENGEFUEHRT WIRD UEBER DEN PFAD, NICHT UEBER DIE POSITION. Ist
//   eine Datei zwischen dem Einlesen der Liste und dem Laden verschwunden
//   (ein Mensch raeumt auf, die Claim-Garantie greift), liefert fast-glob
//   fuer dieses Element KEIN Ergebnis - die Liste wird kuerzer, und ab der
//   Luecke saesse jede Marke an der falschen Datei. Ueber den Pfad kann das
//   nicht passieren.
// ⛔ IM TRY, NICHT NACKT. $('...') WIRFT, wenn der Baustein in diesem
//   Durchgang nicht gelaufen ist oder umbenannt wurde (Handstart aus dem
//   Editor, spaeterer Umbau). Dieser Baustein steht zwischen "Sperre
//   setzen" und "Sperre freigeben" - ein Wurf hier liesse die Sperre bis
//   zum 120-Minuten-Notnagel liegen, und danach wiederholte sich dieselbe
//   Charge. Dieselbe Lehre wie bei "Code" (Pruefung 10m im
//   bau/aufnahmetest.js): Der Riegel gehoert in die Daten, nicht in den
//   Kontrollfluss. Ohne Liste faehrt die Datei eben ohne ihre Marken
//   weiter - hoechstens unnoetige Rechenzeit, kein Stillstand.
const vorher = new Map();
try {
  for (const e of $('Dateien zurueckholen').all()) {
    const p = String((e.json || {}).pfad || '');
    if (p) vorher.set(p, e.json);
  }
} catch (e) {
  console.log('[Anheften] Die Dateiliste ist nicht abrufbar (' + e.message
              + ') - die Dateien fahren ohne ihre Marken weiter.');
}

const raus = [];
let ohne = 0;
for (const e of $input.all()) {
  const b = (e.binary && e.binary.data) || null;
  if (!b) {
    // Kein Binaerfeld: entweder das Leer-Element von alwaysOutputData oder
    // eine Datei, die sich nicht lesen liess (onError). ⛔ NICHT wegwerfen:
    // Eine leere Liste hiesse, dass der naechste Baustein nicht eingeplant
    // wird - dann laeuft "Sperre freigeben" nie, und die Sperre bliebe bis
    // zum 120-Minuten-Notnagel liegen.
    raus.push(e);
    continue;
  }
  const p = String(b.directory || '') + '/' + String(b.fileName || '');
  const alt = vorher.get(p);
  if (!alt) { ohne++; raus.push(e); continue; }
  raus.push({ json: Object.assign({}, alt, e.json || {}), binary: e.binary });
}

if (ohne) {
  // Kein Abbruch - aber sichtbar. Passt ein Pfad nicht, faehrt die Datei
  // ohne ihre Marken weiter (sie wird dann hoechstens unnoetig durch
  // Docling geschickt); stillschweigend soll das nicht geschehen.
  console.log(`[Anheften] ${ohne} von ${raus.length} Dateien ohne Angaben - `
              + `der Pfad aus der Liste und der gelesene Pfad gehen `
              + `auseinander.`);
}
return raus;

const fileName = $input.item.binary?.data?.fileName || '';
const extension = fileName.includes('.')
  ? fileName.split('.').pop().toLowerCase()
  : 'unknown';

let fileType = 'unsupported';

if (extension === 'pdf') fileType = 'pdf';
else if (extension === 'csv') fileType = 'csv';
else if (extension === 'txt') fileType = 'txt';
else if (extension === 'html' || extension === 'htm') fileType = 'html';
else if (extension === 'xlsx' || extension === 'xls') fileType = 'excel';
// Word/PowerPoint: die Unterkette wandelt sie zuerst nach PDF (office-dienst),
// damit Folien/Seiten, Fundstellen und Markierungen funktionieren.
else if (['doc', 'docx', 'odt', 'rtf'].includes(extension)) fileType = 'word';
else if (['ppt', 'pptx', 'odp'].includes(extension)) fileType = 'praesentation';

// ⭐ Die mitgelieferte PDF neben einem Office-Original geht NICHT durch
//   Docling. Ihr Text wird nie hochgeladen (sie ist kein eigenes Dokument),
//   also waere jede Minute Docling-Zeit an ihr verschenkt - bei 293 von 779
//   PDF im gemessenen Bestand ist das der Unterschied zwischen Tagen und
//   Wochen. 'belegquelle' faellt in Ablaufplan 2 durch alle Zweige bis Tika;
//   der Unterablauf liefert damit weiter GENAU EIN Element je Datei, und die
//   Paarung ueber den Dateinamen bleibt heil.
if ($input.item.json.belegquelle === true) fileType = 'belegquelle';

// Massenlauf-Automatik: Hat "Sperre setzen" den Durchgang als Massenlauf
// erkannt, bekommt jedes Dokument die Marke. Die Unterkette liest sie und
// laesst die Bildbeschreibung aus; "Ablage entscheiden" fuehrt die
// Vormerkliste. Fehlt der Knoten (z.B. Handstart), gilt Normallauf.
let massenlauf = false;
try {
  massenlauf = /MASSENLAUF/.test(String($('Sperre setzen').first().json.stdout || ''));
} catch (e) { massenlauf = false; }

return {
  json: {
    ...$input.item.json,
    fileName,
    extension,
    fileType,
    massenlauf
  },
  binary: $input.item.binary
};

const items = $input.all();

return items.map((item) => {
  const doc = item.json;

  // ⛔ doc.schluessel, NICHT $json.schluessel: In einer .map()-Schleife
  //   zeigt $json immer auf das ERSTE Element. Der Waechter haette damit
  //   allen Dateien eines Durchgangs den Schluessel der ersten gegeben -
  //   und genau das ist die Dublettenfalle, die hier beseitigt wird.
  //   Am laufenden System gefunden, nicht beim Lesen.
  const _sl = String(doc.schluessel || '');
  if (!_sl) {
    throw new Error('Kein Schluessel an diesem Dokument - Durchgang '
                    + 'abgebrochen, damit kein unauffindbarer '
                    + 'Bestandseintrag entsteht.');
  }
  const safeName = _sl.replace(/\.[^.]+$/, '').trim();
  const jsonString = JSON.stringify(doc, null, 2);
  const outputFilename = `${safeName}.json`;

  return {
    json: {
      ...doc,
      output_filename: outputFilename,
      output_path: `/files/json/${outputFilename}`,
      json_text: jsonString
    }
  };
});

const items = $input.all();

return items.map((item, index) => {
  const rawContent = item.json.message?.content || '{}';
  const llmData = JSON.parse(rawContent);

  const baseDoc = $('Code').itemMatching(index).json;

  return {
    json: {
      ...baseDoc,
      document_type: llmData.document_type || 'unknown',
      language: llmData.language || 'unknown',
      domain: llmData.domain || 'unknown',
      subdomain: llmData.subdomain || 'unknown',
      methods: llmData.methods || [],
      keywords: llmData.keywords || [],
      tags: llmData.tags || [],
      summary: llmData.summary || '',
      llm_model: item.json.model || '',
      llm_done: item.json.done || false
    }
  };
});

// Laeuft, wenn ein Dokument scheitert.
//
// Zwei Dinge passieren hier, und das zweite fehlte frueher:
//   1. Der Grund wird protokolliert.
//   2. Die PDF wird nach aussortiert/ gelegt - sonst liegt sie weiter in
//      input/ und scheitert bei jedem Lauf aufs Neue, ohne dass es
//      jemandem auffaellt.
const items = $input.all();
const zeit = $now.toFormat('yyyy-LL-dd HH:mm:ss');

const dq = s => '"' + String(s).replace(/[\\"$`]/g, m => '\\' + m) + '"';
const raus = [];
for (const item of items) {
  const j = item.json || {};
  const quelle = j.source_path || j.original_path || '';
  const datei = j.filename || (quelle ? quelle.split('/').pop() : 'unbekannt');
  const fehler =
    (item.error && (item.error.message || item.error.description)) ||
    (j.error && (j.error.message || j.error)) ||
    j.errorMessage ||
    'unbekannter Fehler';
  const text = String(fehler).replace(/[\r\n]+/g, ' ').trim().slice(0, 400);

  raus.push({
    json: {
      zeile: `[${zeit}] ${datei} | ${text}`,
      quelle: quelle,
      ziel: j.aussortiert_path || '',
      log: j.aussortiert_log || '',
      bereich: j.bereich || '',
      // Ein fertiger, shell-sicherer Befehl (Apostroph/Anfuehrungszeichen im Namen)
      befehl: (quelle && j.aussortiert_path)
        ? `mkdir -p "$(dirname ${dq(j.aussortiert_path)})" && printf '%s\\n' ${dq(`[${zeit}] ${datei} | ${text}`)} >> ${dq(j.aussortiert_log || '/dev/null')} && mv -n ${dq(quelle)} ${dq(j.aussortiert_path)}`
        : 'true'
    }
  });
}
return raus;

// Welcher Ordner legt in welchem AnythingLLM-Ordner ab?
//
// Die Zuordnung kommt als Text herein (eine Zeile je Bereich,
// "<ordner>\t<ablage>"), nicht als Datei. Grund: n8n legt Dateiinhalte
// mit N8N_DEFAULT_BINARY_DATA_MODE=filesystem auf die Platte, im
// Datensatz steht nur ein Verweis. Wer den fuer den Inhalt haelt, liest
// Unsinn - und merkt es nicht, weil JSON.parse still scheitert.
const roh = ($input.all()[0]?.json?.stdout) || '';
const karte = {};
for (const zeile of roh.split('\n')) {
  const [bereich, ablage] = zeile.split('\t');
  if (bereich && bereich.trim()) karte[bereich.trim()] = (ablage || bereich).trim();
}

if (!Object.keys(karte).length) {
  // Kein stiller Rueckfall. Ohne Karte wuerde jedes Dokument im Ordner
  // seines Bereichsnamens landen statt im vorgesehenen - und ein
  // Arbeitsbereich haette seinen Bestand in zwei Ordnern liegen.
  // Das faellt niemandem auf und laesst sich hinterher nicht mehr
  // auseinanderhalten. Deshalb hier Schluss.
  throw new Error('Keine bereich.json gefunden - Durchgang abgebrochen, ' +
                  'damit nichts am falschen Ort abgelegt wird.');
}
return [{ json: { karte, anzahl: Object.keys(karte).length } }];

// Erst nachsehen, dann ablegen.
//
// Frueher wanderte die PDF ins Archiv, sobald der Text extrahiert
// war - lange bevor feststand, ob sie im Arbeitsbereich ankommt. Zwei
// Dokumente lagen dadurch im Archiv, ohne im Bestand zu sein. Sie galten
// als erledigt und waeren nie wieder angefasst worden.
//
// Deshalb hier: Was sich nachweisen laesst, geht ins Archiv. Alles andere
// nach aussortiert - lieber ein Dokument zu viel dort (es faellt auf und
// laesst sich zurueckschieben) als eines faelschlich im Archiv.
const dokumente = $('Code').all().map(i => i.json);

// Was meldet der Arbeitsbereich nach dem Einbetten?
const angekommen = [];
for (const e of $input.all()) {
  const w = (e.json && e.json.workspace) || {};
  for (const d of (w.documents || [])) {
    const s = String(d.docpath || d.filename || d.location || d.name || '');
    if (s) angekommen.push(s.split('/').pop().toLowerCase());   // nur der Dateiname, kein Ordner
  }
}

// Namen auf die Grundform bringen - AnythingLLM schreibt sie um
// (Leerzeichen zu Bindestrichen, Umlaute ohne Punkte, Klammern weg).
const grund = (s) => String(s)
  .normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
  .replace(/ß/g, 'ss')
  .replace(/[^A-Za-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .toLowerCase();

// AnythingLLM haengt '.md-<uuid>.json' an - das faellt weg, dann wird EXAKT verglichen.
// Vorher galt ein Teilstring: 'dvs-2213' fand 'dvs-2213-1' (Fund 01.09.).
const kern = g => g.replace(/-md-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}-json$/, '').replace(/-(md|pdf|docx?|xlsx?|pptx?)$/, '');
const gefunden = angekommen.map(g => kern(grund(g)));
const zeit = $now.toFormat('yyyy-LL-dd HH:mm:ss');

// Massenlauf-Automatik: ohne Bildbeschreibung aufgenommen? Dann in die
// Vormerkliste <bereich>/bilder-nachholen.txt - die Bilder werden spaeter
// nachgereicht, das Dokument ist aber ab jetzt durchsuchbar und belegbar.
let massenlauf = false;
try {
  massenlauf = /MASSENLAUF/.test(String($('Sperre setzen').first().json.stdout || ''));
} catch (e) { massenlauf = false; }

// VERLUST-WAECHTER: Was in diesem Durchgang klassifiziert wurde, aber hier
// nicht mehr ankommt, ist in der Kette verloren gegangen. Das gehoert ins
// Protokoll - sonst bleibt es stumm in input/ liegen, wird beim naechsten
// Durchgang erneut verarbeitet und irgendwann kommentarlos aussortiert.
let verloren = [];
try {
  const alle = $('Dateien klassifizieren').all().map(i => String((i.json && i.json.fileName) || ''));
  const da = new Set(dokumente.map(d => String(d.filename || '')));
  verloren = alle.filter(n => n && !da.has(n));
} catch (e) { verloren = []; }
// Shell-sicher in doppelten Anfuehrungszeichen: nur \ " $ ` sind darin besonders.
// Vorher brach ein Apostroph im Dateinamen (Mueller's Bericht.pdf) den EINEN
// Ablage-Befehl des ganzen Durchgangs - kein Dokument wurde abgelegt (Fund 01.09.).
const dq = s => '"' + String(s).replace(/[\\"$`]/g, m => '\\' + m) + '"';
const verlustEintrag = (verloren.length && dokumente.length)
  ? [{ json: {
      datei: verloren.join(', '), bereich: dokumente[0].bereich,
      angekommen: false, ziel: 'input (verblieben)', massenlauf,
      befehl: verloren.map(n =>
        `printf '%s\\n' ${dq(`[${zeit}] ${n} | in diesem Durchgang nicht bis zur Ablage gekommen (Kette unterbrochen) - bleibt in input/, naechster Durchgang versucht es erneut`)} >> ${dq(dokumente[0].aussortiert_log)}`
      ).join(' && '),
    }}]
  : [];

// ⛔ Ein leeres Ergebnis ist KEIN Erfolg, auch wenn der Name im
//    Arbeitsbereich auftaucht.
//
//    Gemessen 21.09.: .jpg und .tif liefern bei Tika HTTP 200 und NULL
//    Zeichen; 16 von 788 PDF sind leer, beschaedigt oder gar keine PDF.
//    "Nicht-PDF vereinheitlichen" setzt zwar ein Fehlerfeld, aber hier
//    entschied bisher ALLEIN der Namensvergleich - eine leere Datei wanderte
//    also ins Archiv und galt als aufgenommen. Damit waere auch der geplante
//    Neu-Einlesevorgang durch leere Dokumente abnehmbar gewesen.
//
// ⭐ SEIT 24.09. stehen MINDESTZEICHEN, VORGESEHEN und KORRESPONDENZ im
//   Baustein "Code" - also VOR dem Upload. Hier standen sie hinter ihm: Eine
//   Datei mit unvorgesehener Endung wurde erst hochgeladen und eingebettet
//   und dann aussortiert; ihr Eintrag blieb im Arbeitsbereich stehen.
//   Dieser Baustein liest die Marken nur noch ab (d.endung, d.korrespondenz,
//   d.nicht_vorgesehen, d.leer) und entscheidet den ORT.
const MINDESTZEICHEN = Number(dokumente[0] && dokumente[0].mindestzeichen) || 20;

// ⛔ POSITIVLISTE. Bis zum 22.09. entschied allein die Textlaenge: Kam aus
//   einer Datei irgendwie mehr als MINDESTZEICHEN heraus, galt sie als
//   Dokument. Gemessen am KAP-Bestand gehen 386 Dateien in Formaten, die
//   niemand vorgesehen hat, ungefragt an Tika (72x .001, 34x .tra,
//   33x .tsx, 32x .inf, 9x .sav ...). Aus einer Binaerdatei kommt fast
//   immer irgendein Zeichensalat - und der landete als "Dokument" im
//   Bestand, durchsuchbar und zitierfaehig.
//
//   Fail-closed, wie ueberall sonst in dieser Anlage: Was nicht auf der
//   Liste steht, wird aussortiert MIT Begruendung. Verloren geht nichts -
//   aussortiert/ spiegelt die Unterordner, und der Schluessel ist auf
//   jeder Stufe derselbe (gemessen). Ein Format, das dazusoll, wird hier
//   eingetragen; die Dateien wandern dann zurueck nach input/ und
//   bekommen exakt denselben Schluessel wie vorher.
const VORGESEHEN_TEXT = String((dokumente[0] && dokumente[0].vorgesehen_liste) || '');

// ⚠ Korrespondenz wird ERKANNT, aber noch nicht aufgenommen.
//   Eine E-Mail ist keine Fachunterlage. Steht in interner Post das Wort
//   "Prozessimulation", zitiert die Anlage sie auf eine Fachfrage, als
//   waere sie eine Spezifikation - ihr fehlt die ART eines Dokuments
//   (entschieden 22.09.). Bis die da ist, bleiben Mails draussen: sichtbar,
//   mit eigener Begruendung, nicht stillschweigend. 65 Stueck im
//   KAP-Bestand.
const abgelegt = dokumente.map((d) => {
  const laenge = Number(d.text_length || 0);
  const leer = d.leer === true;
  const endung = String(d.endung || '');
  const korrespondenz = d.korrespondenz === true;
  const nicht_vorgesehen = d.nicht_vorgesehen === true;
  // ⛔ Die Positivliste kam im Baustein "Code" nicht an. Dann ist
  //   nicht_vorgesehen zwar gesetzt (fail-closed), aber die Endung ist
  //   nicht der Grund - der gehoert zuerst ins Protokoll.
  const listen_fehlen = d.listen_fehlen === true;
  // ⭐ Verglichen wird der ABDRUCK, nicht der Name. Er ist zehn Zeichen aus
  //   a-z0-9 und ueberlebt, was AnythingLLM mit Namen macht ('&' wird 'and',
  //   '%' wird 'percent') - eine Wortersetzung ueberlebt die Normalisierung
  //   und verschiebt den Namen dauerhaft (BUGS_UND_FIXES.md 11).
  //   Kein SHA-256 noetig: Den Abdruck hat der Schluessel-Dienst mitgegeben.
  const abdruck = String(d.abdruck || '');
  // ⭐ Die BELEGQUELLE wird nicht im Arbeitsbereich gesucht. Unter ihrem
  //   Abdruck steht das Office-Original - und das kann aus einem frueheren
  //   Durchgang stammen und in dieser Antwort gar nicht vorkommen. Sie
  //   gehoert trotzdem ins Archiv: dort ist sie die Seitenquelle, auf die
  //   die Belege des Originals springen.
  const drin = d.nur_beleg === true
    ? !!abdruck
    : (!leer && !korrespondenz && !nicht_vorgesehen
       && !!abdruck && gefunden.some(g => g.includes(abdruck)));
  const quelle = d.source_path;
  const ziel = drin ? d.archiv_path : d.aussortiert_path;
  // Der WAHRE Grund zuerst: Scheiterte schon die Textextraktion, steht das
  // hier - nicht das nachgelagerte "nicht wiedergefunden" (gemessen 25.08.).
  // Shell-Sonderzeichen raus, die Zeile steht in doppelten Anfuehrungszeichen.
  // ⭐ Die Formatgruende ZUERST: Bei einer JPG ist "kein Text gewonnen"
  //   zwar wahr, aber es ist nicht der Grund - und ein Mensch, der das
  //   Protokoll liest, sucht dann den Fehler in der Datei statt in der
  //   Liste. Der WAHRE Grund gehoert nach vorn (gemessen 25.08. am
  //   nachgelagerten "nicht wiedergefunden").
  const begruendung = listen_fehlen
    ? `Positivliste nicht angekommen - der Baustein "Code" bekam aus ` +
      `"Nur ein Bereich je Durchgang" keine Liste der vorgesehenen ` +
      `Formate. Ohne sie laesst sich nicht entscheiden, was ein Dokument ` +
      `ist; dieser Durchgang laedt deshalb NICHTS hoch - auch kein ` +
      `vorgesehenes Format. Nach aussortiert/ verschoben, nicht ins ` +
      `Archiv. Das ist KEIN Befund ueber diese Datei, sondern ein Fehler ` +
      `in der Kette: Pruefen, ob der Baustein noch so heisst und seine ` +
      `Liste VORGESEHEN ausgibt. Danach die Datei aus aussortiert/ zurueck ` +
      `nach input/ legen - von dort bekommt sie denselben Schluessel wie ` +
      `vorher`
    : korrespondenz
    ? `Korrespondenz (.${endung}) - wird derzeit nicht aufgenommen. Eine ` +
      `E-Mail ist keine Fachunterlage; solange die Anlage die ART eines ` +
      `Dokuments nicht kennt, wuerde sie interne Post auf Fachfragen ` +
      `zitieren. Bleibt hier liegen und kann spaeter mit demselben ` +
      `Schluessel nachgeholt werden`
    : nicht_vorgesehen
    ? `Format nicht vorgesehen (.${endung || 'ohne Endung'}) - nur ` +
      `${VORGESEHEN_TEXT} werden aufgenommen. Bilder, Archive, ` +
      `CAD- und Messgeraetedateien liefern keinen belegbaren Text. ` +
      `Bleibt hier liegen; soll das Format dazu, wird es in VORGESEHEN ` +
      `eingetragen und die Datei kommt mit demselben Schluessel zurueck`
    : d.fehler
    ? `Textextraktion gescheitert - ${String(d.fehler).replace(/[$\`\\"]/g, "'").slice(0, 300)}. ` +
      `PDF pruefen (Schutz? beschaedigt? nur Bilder?) - notfalls neu drucken/als PDF exportieren und erneut hochladen`
    : leer
      ? `kein Text gewonnen (${laenge} Zeichen, Mindestmass ${MINDESTZEICHEN}) - ` +
        `Datei pruefen: leer? beschaedigt? reines Bild ohne Texterkennung? ` +
        `Nicht ins Archiv, weil ein leeres Dokument im Bestand weder auffindbar ` +
        `noch belegbar ist und dennoch als aufgenommen gaelte`
      : !abdruck
        ? `kein Schluessel vergeben - ohne ihn ist das Dokument im Bestand ` +
          `nicht wiederzufinden. Nicht ins Archiv.`
        : `im Arbeitsbereich nicht wiedergefunden - Aufnahme unvollstaendig`;
  const zeile = drin ? '' : `[${zeit}] ${d.filename} | ${begruendung}`;

  // Der Befehl legt die Datei ab und schreibt bei Misserfolg die
  // Begruendung daneben. "-n": eine vorhandene Datei am Ziel wird nicht
  // ueberschrieben.
  // ⛔ d.vormerk_path, NICHT dirname(dirname(ziel)). Das traf den Bereich nur
  //   bei einer FLACH abgelegten Datei; bei <bereich>/archiv/A/B/x.pdf kam
  //   <bereich>/archiv/A heraus. So entstand je Ordnerebene eine eigene
  //   bilder-nachholen.txt, und pruef_proxy.py:559 - das einzige, was die
  //   Liste liest und aufraeumt - kennt nur <bereich>/bilder-nachholen.txt.
  // ⚠ Eine Belegquelle wird NIE vorgemerkt: Ihre Bilder gehoeren dem
  //   Original, und nachgereicht wird an dessen Eintrag.
  const vormerken = (drin && !d.nur_beleg && (massenlauf || d.ohne_bilder))
    ? ` && printf '%s\\n' ${dq(d.filename)} >> ${dq(d.vormerk_path)}`
    : '';
  // ⛔ Die Belegquelle darf eine schon abgelegte PDF NICHT ueberschreiben.
  //   Liegt am Ziel bereits die aus dem Original gewandelte PDF, ist GENAU
  //   DIE die richtige: Aus ihr stammt der Text und damit die Seitenzahlen im
  //   Katalog. Die mitgelieferte PDF geht dann nach aussortiert - mit Grund,
  //   statt in input/ liegenzubleiben und jeden Durchgang erneut aufgegriffen
  //   zu werden (mv -n meldet keinen Fehler, wenn es nichts tut - deshalb
  //   wird auf die QUELLE geprueft, nicht auf den Rueckgabewert).
  const belegzeile = `[${zeit}] ${d.filename} | mitgelieferte PDF neben ` +
    `dem Office-Original ${d.traeger || ''} - am Ablageort liegt bereits die ` +
    `aus dem Original gewandelte PDF, und aus IHR stammen Text und ` +
    `Seitenzahlen im Katalog. Kein eigenes Dokument, kein eigener Eintrag`;
  const befehl = d.nur_beleg
    ? `mkdir -p "$(dirname ${dq(ziel)})" && mv -n ${dq(quelle)} ${dq(ziel)} ; ` +
      `if [ -e ${dq(quelle)} ]; then mkdir -p "$(dirname ${dq(d.aussortiert_path)})" && ` +
      `printf '%s\n' ${dq(belegzeile)} >> ${dq(d.aussortiert_log)} && ` +
      `mv -f ${dq(quelle)} ${dq(d.aussortiert_path)} ; fi`
    : drin
    ? `mkdir -p "$(dirname ${dq(ziel)})" && mv -n ${dq(quelle)} ${dq(ziel)}${vormerken}`
    : `mkdir -p "$(dirname ${dq(ziel)})" && ` +
      `printf '%s\n' ${dq(zeile)} >> ${dq(d.aussortiert_log)} && ` +
      `mv -n ${dq(quelle)} ${dq(ziel)}`;

  return { json: {
    datei: d.filename, bereich: d.bereich,
    angekommen: drin,
    ziel: d.nur_beleg ? 'archiv (Belegquelle, nicht hochgeladen)'
                      : (drin ? 'archiv' : 'aussortiert'),
    nur_beleg: d.nur_beleg === true, traeger: d.traeger || '',
    zeichen: laenge, leer,
    massenlauf, bilder_nachholen: drin && (massenlauf || d.ohne_bilder),
    befehl,
  }};
});
// ⚠ EIN Auftrag fuer alle: 'Ablegen' (Befehls-Baustein) fuehrte bei drei
//   Auftraegen nur den ersten aus - zwei eingebettete Dokumente blieben
//   stumm in input/ (gemessen 25.08., Durchgang #279). Statt auf das
//   Je-Element-Verhalten des Bausteins zu bauen, wandern alle Befehle in
//   EINE Zeile (durch ';' getrennt: ein gescheiterter mv haelt die anderen
//   nicht auf). Die Einzelheiten bleiben zur Nachvollziehbarkeit im Element.
const alle = abgelegt.concat(verlustEintrag);
return [{ json: {
  anzahl: alle.length,
  leer_aussortiert: abgelegt.filter(x => x.json.leer).length,
  dokumente: alle.map(x => ({ datei: x.json.datei, ziel: x.json.ziel, angekommen: x.json.angekommen })),
  massenlauf,
  befehl: alle.map(x => x.json.befehl).filter(Boolean).join(' ; ') || 'true',
}}];

// Ein Durchgang, ein Arbeitsbereich - und nichts doppelt.
//
// ZWEI Aufgaben, weil beide dieselbe Dateiliste brauchen:
//
// 1. Nur EIN Bereich je Durchgang. Geholt wird aus allen Bereichen
//    zugleich (*/input/*), beim Hochladen kann aber nur ein Ablageordner
//    gewinnen - sonst landen die Unterlagen des einen im anderen.
//
// 2. Nichts, was schon im Bestand liegt. Der Ablauf verschiebt die PDF
//    erst am Ende ins Archiv; bricht er vorher ab, liegt sie weiter in
//    input und wuerde erneut hochgeladen. So entstanden schon einmal mehrere
//    Fassungen desselben Dokuments.
//
//    ⚠ Solche Dateien werden hier nur UEBERSPRUNGEN, nicht abgelegt.
//      Sie bleiben in input liegen und fallen bei jedem Durchgang erneut
//      durch diesen Filter. Das kostet nichts (keine Texterkennung, kein
//      Modell), sieht aber nach unerledigter Arbeit aus, obwohl das
//      Dokument laengst da ist. Wer aufraeumt, verschiebt sie nach
//      archiv/ - der Bestand aendert sich dadurch nicht.
const alle = $input.all();
if (!alle.length) return [];

// ⭐ WOHER NAME UND ORDNER KOMMEN (06.10.).
//
// ⛔ Bis heute kamen beide aus item.binary.data - also aus einem Baustein,
//   der die Datei dafuer erst VOLLSTAENDIG gelesen hatte. Genau das hat die
//   Platte des Servers vollgeschrieben: "Daten vom Server laden" las jede
//   Datei des Eingangs (gemessen 5.837 Dateien = 18 GB), und erst DANACH
//   schnitt "Menge begrenzen" auf 25 zu. Mit
//   N8N_DEFAULT_BINARY_DATA_MODE=filesystem landet alles Gelesene je
//   Ausfuehrung auf der Platte - 116,8 GB in 8.355 Ausfuehrungsordnern,
//   danach ENOSPC und stundenlang "0 zu verarbeiten" bei vollem Eingang.
//
// ⭐ Jetzt kommt die Liste aus "Dateiliste einlesen" (find, nur Namen) und
//   steht im json. Gelesen wird erst HINTER der Sperre, und nur die Charge.
//   Dieser Baustein braucht dafuer weiterhin ALLE Namen - Bereichswahl und
//   Wegraeum-Befehl haengen daran -, aber eben nur die Namen.
//
// ⚠ Der Rueckfall auf binary bleibt: bau/aufnahmetest.js und
//   bau/ablauf_pruefen.py fahren diesen Baustein auch mit Elementen, wie
//   sie "Daten vom Server laden" liefert, und ein Handstart aus dem Editor
//   kann es ebenso. Eine Quelle wegzunehmen, die noch jemand benutzt, waere
//   genau die Art stiller Bruch, die hier sonst ueberall angeschrieben ist.
// ⚠ DIE HILFSFUNKTION ANGABE MUSS DIE ERSTE DER DREI BLEIBEN.
//   bau/ablauf_pruefen.py schneidet fuer test_bereichserkennung den Block
//   ab ihrer Deklaration bis zu dem von nameVon heraus und faehrt ihn
//   ALLEIN mit node. Rutscht sie hinter bereichVon, stirbt der Ausschnitt
//   sofort an "ReferenceError: angabe is not defined" - und ein
//   Pruefstand, der abstuerzt, meldet keine Fehler, sondern gar nichts.
//   Genau daran ist er am 24.09. elf Tage unbemerkt gestorben.
// ⛔ UND DIE MARKERZEICHENFOLGE DARF IN KEINEM KOMMENTAR STEHEN: Der
//   Ausschnitt wird mit find() gesucht und traefe sonst den Kommentar
//   statt die Deklaration (nachgestellt 06.10.: "SyntaxError: Missing
//   initializer in const declaration").
const angabe = (item) => {
  const b = (item && item.binary && item.binary.data) || null;
  if (b && (b.fileName || b.directory)) return b;
  return (item && item.json) || {};
};
const bereichVon = (item) => {
  const b = angabe(item);
  const teile = String(b.directory || '').split('/').filter(Boolean);
  // ⛔ NICHT das vorletzte Segment: Bei einer Datei in einem Unterordner
  //   (.../<bereich>/input/Normen) ist das "Normen", bei einer flachen
  //   "input". Folge waere der Upload in den FALSCHEN Arbeitsbereich - die
  //   Ablage der ersten Datei gilt fuer alle (BUGS_UND_FIXES.md 7).
  //   Der Nachbarknoten "Code" rechnet seit seinem Fix schon so.
  const iInput = teile.lastIndexOf('input');
  return iInput > 0 ? teile[iInput - 1] : (teile[teile.length - 2] || '');
};
const nameVon = (item) => String(angabe(item).fileName || '');

// Namen auf die Grundform bringen - AnythingLLM schreibt sie um
// (Leerzeichen zu Bindestrichen, Umlaute ohne Punkte, Klammern weg).
const grund = (s) => String(s)
  .normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
  .replace(/ß/g, 'ss')
  .replace(/[^A-Za-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .toLowerCase();

// Was liegt schon im Bestand?
const bekannt = new Set();
try {
  const antwort = $('Bestand abfragen').first().json;
  const ordner = (antwort.localFiles && antwort.localFiles.items) || [];
  for (const o of ordner) {
    for (const d of (o.items || [])) {
      const roh = String(d.name || '')
        .replace(/\.json$/i, '')
        .replace(/-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i, '')
        .replace(/\.md$/i, '');
      if (roh) bekannt.add(grund(roh));
    }
  }
} catch (e) {
  // Ohne Bestandsliste NICHT einfach weitermachen: Dann wuerde jedes
  // Dokument erneut hochgeladen, und die Dubletten waeren zurueck.
  throw new Error('Bestand nicht abfragbar - Durchgang abgebrochen, damit ' +
                  'nichts doppelt aufgenommen wird.');
}

// 3. Was gar kein Dokument ist, faellt hier raus.
//
//    Gemessen 21.09.: Von 16 PDF, an denen Docling scheiterte, waren NEUN
//    macOS-Metadateien - je exakt 4.096 Byte, Kennung 00 05 16 07. macOS
//    legt sie beim Kopieren auf fremde Dateisysteme zu jeder Datei an; sie
//    heissen wie das Original mit vorangestelltem "._" und enthalten keinen
//    Inhalt. Sie zaehlten bis dahin in jeder Bestandszahl mit und liefen
//    jeden Durchgang erneut durch die ganze Kette, um am Ende zu scheitern.
//    Dass der Bestand von einem Mac stammt, zeigen auch 142 .DS_Store.
const NICHTDOKUMENT = (n) => {
  const b = String(n);
  // Office-Sperrdatei: entsteht beim Oeffnen eines Word-, Excel- oder
  // PowerPoint-Dokuments und bleibt nach einem Absturz liegen. Ein paar
  // hundert Byte, Inhalt ist nur, wer die Datei offen hat - aber sie
  // traegt die Endung des Originals und laeuft dadurch in den
  // Office-Zweig. Gemessen 23.09. im KAP-Bestand: 54 Stueck
  // (.doc 26, .pptx 14, .docx 10, .xlsx 3, .xlsm 1).
  if (b.startsWith('~$')) return 'Office-Sperrdatei';
  if (b.startsWith('._')) return 'macOS-Metadatei';          // AppleDouble
  if (b === '.DS_Store' || b === 'Thumbs.db') return 'Ordner-Merkdatei';
  if (b === 'desktop.ini' || b === '.localized') return 'System-Merkdatei';
  if (b.startsWith('.')) return 'versteckte Datei';
  // ⛔ DIE EIGENE BUCHHALTUNG DER ANLAGE. Gemessen 25.09.: Im
  //   Arbeitsbereich stand 'kap-bilder-nachholen--kh26rcuhlk.md' - die
  //   Vormerkliste fuer nachzureichende Bilder, aufgenommen als waere sie
  //   eine Fachunterlage. Sie traegt die Endung .txt und steht damit in
  //   VORGESEHEN; nichts hat sie aufgehalten.
  // ⛔ Der Proxy kennt diese Namen laengst (laufstand.STEUER), die Aufnahme
  //   kannte KEINEN davon - die beiden Listen hatten null Ueberschneidung.
  //   Eine Seite weiss, was Buchhaltung ist, die andere frisst sie.
  // ⚠ Sie steht damit an ZWEI Stellen, weil n8n kein Python liest. Wer
  //   hier einen Namen ergaenzt, ergaenzt ihn in laufstand.STEUER MIT -
  //   sonst laufen sie wieder auseinander, und es faellt erst auf, wenn
  //   eine Protokolldatei im Bestand steht.
  if (['bereich.json', 'metadaten.json', 'rolle.json', 'prompt.md',
       'kategorien.txt', 'bilder-nachholen.txt', 'aussortiert.log',
       'loeschen.log', 'claim.log'].indexOf(b) >= 0)
    return 'Buchhaltung der Anlage';
  return '';
};

// ⭐ DIE POSITIVLISTE - UND ZWAR HIER, VOR DER SPERRE (05.10.).
//
// ⛔ Bis heute siebte dieser Baustein nur nach NICHTDOKUMENT, Bestand und
//   fremdem Bereich. Eine Datei mit nicht vorgesehener Endung (jpg, tif,
//   asc, tsx ...) fiel durch alle drei Siebe und wurde erst viel spaeter in
//   "Ablage entscheiden" weggeraeumt - HINTER dem Upload. Besteht eine
//   Charge nur aus solchen Dateien, liefert "Nur Dokumente hochladen" ein
//   leeres [], die Schleife laeuft nicht an, "Ablage entscheiden" und
//   "Sperre freigeben" laufen nie - die Sperre bleibt bis zum
//   120-Minuten-Notnagel liegen, und danach wiederholt sich dieselbe Charge
//   identisch. Nachgerechnet an der echten Dateiliste (6.546 Zeilen,
//   Chargen zu 25 in readdir-Reihenfolge): 85 von 247 Durchgaengen (34 %)
//   enthalten kein einziges hochladbares Dokument, der erste schon als
//   Nr. 3 - ein Ordner mit 25x .jpeg, einer mit zwei vollen Chargen zu
//   25x .jpg, einer mit 13x .asc und 12x .tsx. Dieselbe Falle, die fuer
//   NICHTDOKUMENT heute morgen geschlossen wurde, nur eine Tuer weiter.
//
// ⚠ EINE QUELLE. Die Liste stand bis heute im Baustein "Code" und wurde
//   von dort als Text an "Ablage entscheiden" weitergereicht. Gebraucht
//   wird sie jetzt, BEVOR "Code" ueberhaupt laeuft - also zieht sie hierher,
//   in denselben Baustein, der schon NICHTDOKUMENT besitzt und den
//   Wegraeum-Befehl baut. "Code" liest sie ueber
//   $('Nur ein Bereich je Durchgang').first() und reicht sie wie bisher als
//   vorgesehen_liste weiter. Eine zweite Fassung nachzubauen waere genau
//   der Fehler, vor dem der Kommentar an NICHTDOKUMENT warnt.
//
//   Gemessen am KAP-Bestand gehen 386 Dateien in Formaten, die niemand
//   vorgesehen hat, ungefragt an Tika (72x .001, 34x .tra, 33x .tsx,
//   32x .inf, 9x .sav ...). Aus einer Binaerdatei kommt fast immer
//   irgendein Zeichensalat - und der landete als "Dokument" im Bestand.
//   Fail-closed: Was nicht auf der Liste steht, wird aussortiert MIT
//   Begruendung. Verloren geht nichts - aussortiert/ spiegelt die
//   Unterordner, und der Schluessel ist auf jeder Stufe derselbe.
const VORGESEHEN = ['pdf', 'doc', 'docx', 'odt', 'rtf',
                    'ppt', 'pptx', 'odp',
                    'xls', 'xlsx', 'xlsm',
                    'csv', 'txt', 'md', 'html', 'htm'];

// ⚠ Korrespondenz wird ERKANNT, aber noch nicht aufgenommen: Eine E-Mail
//   ist keine Fachunterlage (entschieden 22.09.). 65 Stueck im KAP-Bestand.
// ⛔ Sie wird hier bewusst NICHT weggeraeumt. Ihre Begruendung in
//   "Ablage entscheiden" ist eine Aussage ueber den INHALT ("kann spaeter
//   mit demselben Schluessel nachgeholt werden"), keine ueber das
//   Dateisystem - und diese Entscheidung gehoert nicht in einen
//   Fehlerbehebungs-Durchgang. Preis: Eine Charge aus lauter .msg/.eml
//   bleibt der eine Fall, der weiterhin in den 120-Minuten-Notnagel laufen
//   kann. Wer das aendern will, nimmt KORRESPONDENZ in ABFALL mit auf.
const KORRESPONDENZ = ['msg', 'eml'];

// Die Endung aus dem Dateinamen - derselbe Name, den auch der
// Schluessel-Dienst sieht, und dieselbe Rechnung wie im Baustein "Code".
const ENDUNG = (n) => {
  const t = String(n).split('.');
  return t.length > 1 ? t.pop().toLowerCase() : '';
};
const NICHT_VORGESEHEN = (n) => {
  const e = ENDUNG(n);
  if (KORRESPONDENZ.indexOf(e) !== -1) return '';
  if (VORGESEHEN.indexOf(e) !== -1) return '';
  return 'Format nicht vorgesehen (.' + (e || 'ohne Endung') + ')';
};

// Was den Eingang verlassen muss, bevor die Sperre faellt - beides
// zusammen. Die Reihenfolge entscheidet ueber den GRUND im Protokoll:
// eine 'Thumbs.db' ist eine Merkdatei, nicht "Endung .db nicht vorgesehen".
const ABFALL = (n) => NICHTDOKUMENT(n) || NICHT_VORGESEHEN(n);

// ⚠ ZWISCHEN 'const NICHTDOKUMENT' UND 'const ersterBereich' DARF NICHTS
//   STEHEN, was den uebrigen Baustein braucht. bau/nichtdokumente_wegraeumen.py
//   und bau/ablauf_pruefen.py schneiden GENAU diesen Abschnitt heraus und
//   fuehren ihn allein mit node aus - eine Regel, zwei Leser. Seit dem
//   24.09. stand die Belegquellen-Rechnung mit `for (const item of alle)`
//   darin; beide Werkzeuge starben seither sofort an
//   "ReferenceError: alle is not defined" (nachgestellt 05.10., der
//   Pruefstand kam nicht ueber seinen ERSTEN Test hinaus). Deshalb steht
//   sie jetzt weiter unten.

// ⛔ Welcher Bereich an der Reihe ist, entscheidet der erste ECHTE Eintrag -
//   keine Merkdatei. Vorher stand hier bereichVon(alle[0]). Lag im Eingang
//   eines Bereichs nur Abfall, bestimmte genau dieser Abfall den Bereich,
//   und weil danach nichts uebrig blieb, lief der Durchgang leer: "Menge
//   begrenzen" bekam nichts, "Sperre setzen" wurde nie ausgefuehrt (auch
//   seine Claim-Garantie nicht), und alle anderen Bereiche hungerten mit.
//   Gemessen 05.10.: vier 'bilder-nachholen.txt', elf Tage, rund 3.000
//   Leerlaeufe.
const ersterBereich = bereichVon(alle.find(i => !ABFALL(nameVon(i))) || alle[0]);

// ⭐ DIE MITGELIEFERTE PDF (24.09.). In Kundenordnern liegt neben dem
//   Word-/PowerPoint-Original haeufig die daraus exportierte PDF - gemessen
//   am Bestand: 293 von 779 PDF haben ein gleichnamiges Office-Original
//   daneben. Das Dokument ist das ORIGINAL; die PDF ist nur die Quelle fuer
//   den Belegsprung (dieselbe Regel wie in pruef_proxy._schluessel_der_datei).
//
//   Hier wird sie nur MARKIERT, nicht aussortiert: Wer sie wegwirft, laesst
//   sie in input/ liegen, und die Claim-Garantie schiebt sie nach 180 Minuten
//   nach aussortiert - nachdem sie 180 Durchgaenge lang jede Minute erneut
//   durch Docling gelaufen ist. Die Marke steuert stattdessen den billigen
//   Weg durch Ablaufplan 2 (Tika statt Docling).
//
// ⚠ Das hier ist eine LISTENPRUEFUNG, kein Blick auf die Platte: Sie greift,
//   wenn Original und PDF im selben Durchgang im selben Ordner liegen. Der
//   Fall "Original liegt schon im Archiv" faellt hier durch - er wird beim
//   Schluessel erkannt (mkmd-Dienst, belegquelle.py), und DORT entscheidet
//   sich auch, was hochgeladen wird. Diese Marke spart nur Rechenzeit.
const OFFICE_ORIGINAL = ['.docx', '.doc', '.odt', '.rtf',
                         '.pptx', '.ppt', '.odp'];
const ordnerVon = (item) => String(angabe(item).directory || '');
const _nachbarn = new Set();
for (const item of alle) {
  const n = nameVon(item);
  const i = n.lastIndexOf('.');
  if (i > 0 && OFFICE_ORIGINAL.indexOf(n.slice(i).toLowerCase()) !== -1) {
    _nachbarn.add(ordnerVon(item) + '\u0000' + n.slice(0, i).toLowerCase());
  }
}
const istBelegquelle = (item) => {
  const n = nameVon(item);
  if (!n.toLowerCase().endsWith('.pdf')) return false;
  return _nachbarn.has(ordnerVon(item) + '\u0000' + n.slice(0, -4).toLowerCase());
};

// ⭐ DER WEG DER NICHT-DOKUMENTE AUS DEM EINGANG (05.10.).
//
// ⛔ Bis heute stand an dieser Stelle nur `continue`: erkannt, uebersprungen,
//   liegen gelassen. Gemessen am laufenden System: vier 'bilder-nachholen.txt'
//   lagen ELF TAGE im Eingang eines Bereichs, wurden in jedem Durchgang
//   richtig als Nicht-Dokument erkannt und in jedem Durchgang liegen
//   gelassen - rund 3.000 Leerlaeufe.
//
// ⚠ WARUM NICHT DEN WEG DER BELEGQUELLE ueber "Ablage entscheiden"?
//   Weil die Belegquelle mitfaehrt: Neben ihr liegt immer ihr
//   Office-Original, der Durchgang hat also IMMER etwas hochzuladen, und
//   damit laeuft die Schleife, laeuft "Ablage entscheiden", laeuft
//   "Sperre freigeben". Ein Eingang aus lauter Nicht-Dokumenten hat das
//   nicht: "Nur Dokumente hochladen" gaebe eine leere Liste zurueck, und
//   ein Baustein mit leerem Eingang wird gar nicht erst ausgefuehrt. Dann
//   legt niemand etwas ab UND die Sperre bliebe bis zum
//   120-Minuten-Notnagel liegen - dieselbe Dichtmachung, gegen die
//   "Sperre setzen" schon seine Leerlauf-Pruefung bekommen hat. Der
//   fertige Befehl entsteht deshalb HIER und wird von "Sperre setzen"
//   ausgefuehrt: vor der Sperre, vor der Unterkette, vor jedem Upload.
//   Damit ist die Datei nicht gewandelt, nicht hochgeladen, nicht
//   eingebettet und steht in keinem Katalog.
//
// ⚠ WAS ein Nicht-Dokument ist, bleibt oben in NICHTDOKUMENT. Hier
//   entsteht nur der Befehl. Eine zweite Fassung der Namensliste in der
//   Shell waere genau der Fehler, vor dem der Kommentar dort warnt.

// Shell-sicher in doppelten Anfuehrungszeichen: nur \ " $ ` sind darin
// besonders (dieselbe Rechnung wie in "Ablage entscheiden").
const dq = s => '"' + String(s).replace(/[\\"$`]/g, m => '\\' + m) + '"';
const zeit = $now.toFormat('yyyy-LL-dd HH:mm:ss');

// ⛔ KEIN dirname(dirname(...)). Bei einer Datei in einem Kundenordner
//   (.../<bereich>/input/KundeA/x.txt) ergibt das den EINGANG selbst; die
//   Datei landete dann in input/aussortiert/ und wuerde von dort im
//   naechsten Durchgang wieder eingesammelt (BUGS_UND_FIXES.md 7, und
//   genau derselbe Verrechner ist diesem Haus heute schon zweimal
//   passiert). Getrennt wird am Segment 'input' - wie im Baustein "Code"
//   und wie in der Claim-Garantie von "Sperre setzen" (${f%%/input/*}).
const ablageOrt = (item) => {
  const name = nameVon(item);
  const teile = String(ordnerVon(item)).split('/').filter(Boolean);
  const i = teile.lastIndexOf('input');
  // Ohne 'input' im Pfad gibt es keinen sicheren Zielort. Dann lieber
  // liegen lassen und zaehlen, als irgendwohin verschieben (fail-closed) -
  // der Parkplatz ist Kundenbestand und wird nie angefasst.
  if (i < 1 || !name) return null;
  const wurzel = '/' + teile.slice(0, i).join('/');
  const unter = teile.slice(i + 1).concat([name]).join('/');
  return {
    quelle: '/' + teile.join('/') + '/' + name,
    // Der Unterordner bleibt erhalten - sonst stossen zwei gleichnamige
    // Merkdateien aus zwei Kundenordnern aufeinander.
    ziel: wurzel + '/aussortiert/' + unter,
    log: wurzel + '/aussortiert/aussortiert.log',
  };
};

const raus = [];
const nichtdok = [];
let fremd = 0, schon = 0, kein_dokument = 0, belegquellen = 0, ohne_ort = 0;
let unvorgesehen = 0;
for (const item of alle) {
  // ⭐ Der Abfall zuerst, und zwar in ALLEN Bereichen. Eine Merkdatei ist
  //   in keinem Bereich Arbeit; sie wegzuraeumen fasst keinen
  //   Arbeitsbereich an (kein Upload, kein Katalog) und verhindert, dass
  //   ein Eingang voller Abfall den naechsten Durchgang erneut blockiert.
  //   Deshalb steht diese Pruefung VOR der Bereichspruefung - die Regel
  //   "ein Bereich je Durchgang" gilt dem Hochladen, nicht dem Wegraeumen.
  const keinDok = NICHTDOKUMENT(nameVon(item));
  const art = keinDok || NICHT_VORGESEHEN(nameVon(item));
  if (art) {
    kein_dokument++;
    if (!keinDok) unvorgesehen++;
    const ort = ablageOrt(item);
    if (!ort) { ohne_ort++; continue; }
    nichtdok.push({ art: art, keinDok: !!keinDok, datei: nameVon(item),
                    quelle: ort.quelle, ziel: ort.ziel, log: ort.log });
    continue;
  }
  if (bereichVon(item) !== ersterBereich) { fremd++; continue; }
  const stamm = grund(nameVon(item).replace(/\.[^.]+$/, ''));
  if (stamm && bekannt.has(stamm)) { schon++; continue; }
  // ⚠ NEUES Element statt item.json anzufassen. Seit dem 06.10. kommt
  //   die Liste aus "Dateiliste aufbereiten" und bringt ihr eigenes json
  //   mit (pfad, muster, fileName, directory) - das darf nicht verloren
  //   gehen, "Daten vom Server laden" braucht 'muster' spaeter. Und beim
  //   Handstart aus dem Editor kann ein Element weiterhin ganz ohne json
  //   ankommen; ein Schreibzugriff darauf waere ein Fehler mitten im
  //   Durchgang.
  if (istBelegquelle(item)) {
    belegquellen++;
    raus.push({ json: Object.assign({}, item.json || {}, { belegquelle: true }),
                binary: item.binary });
    continue;
  }
  raus.push(item);
}
const echte = raus.length;

// Je Datei: Ordner anlegen, verschieben, Grund ins aussortiert.log.
//
// ⚠ mv -f, NICHT mv -n: Liegt am Ziel schon dieselbe Merkdatei aus einem
//   frueheren Durchgang, taete mv -n still gar nichts - es meldet dabei
//   keinen Fehler (das steht so schon bei der Belegquelle in "Ablage
//   entscheiden"), und die Datei bliebe fuer immer im Eingang liegen.
//   Das waere genau der Fehler, der hier behoben wird. Ueberschrieben
//   wird dabei nur Abfall gleichen Namens am selben Ort.
// ⚠ Verkettet mit ';', nicht mit '&&': ein gescheitertes mv darf die
//   uebrigen nicht aufhalten (dieselbe Regel wie in "Ablage entscheiden").
// ⚠ Hoechstens AUF_EINMAL Dateien je Durchgang. 6.435 Namen sind als
//   Befehlszeile ueber 130.000 Zeichen und sprengen ARG_MAX (gemessen
//   23.09. in bau/nichtdokumente_wegraeumen.py). Der Rest kommt im
//   naechsten Durchgang dran - alle fuenf Minuten einer.
//
// ⛔ DIE STUECKZAHL ALLEIN GENUEGT NICHT (05.10.). "Sperre setzen" ist ein
//   executeCommand-Baustein: n8n reicht den ganzen Text als EIN Argument an
//   `sh -c`, und ein einzelnes Argument darf unter Linux hoechstens
//   MAX_ARG_STRLEN gross sein (32 Seiten = 131.072 Byte). Die Begruendung je
//   Datei ist rund 600 Zeichen lang; 200 Dateien ergaben gemessen 161.397
//   Byte - der Baustein waere mit E2BIG gar nicht erst gestartet, und zwar
//   jede Minute neu. Allein die 151 versteckten Dateien im Bestand reichen
//   dafuer aus. Deshalb zusaetzlich ein Budget, dieselbe Grenze wie in
//   bau/nichtdokumente_wegraeumen.py (_pakete, grenze=60000).
//
// ⛔ IN BYTE, NICHT IN ZEICHEN (05.10.). Hier stand `b.length` - das sind
//   UTF-16-ZEICHEN, MAX_ARG_STRLEN zaehlt BYTE. Ein Umlaut ist 2 Byte, ein
//   CJK-Zeichen 3. Gemessen an 400 Dateien mit japanischen Namen: 59.293
//   Zeichen Budget = 71.397 Byte Befehl - das Budget war um ein Fuenftel
//   ueberschritten, ohne dass es jemand merkt. Bei laengeren Namen reisst
//   damit genau die Grenze, die dieser Abschnitt einhalten soll.
const AUF_EINMAL = 200;
const HOECHSTENS_BYTE = 60000;
const _befehle = [];
let _gezaehlt = 0;   // in BYTE, siehe oben
for (const n of nichtdok) {
  if (_befehle.length >= AUF_EINMAL) break;
  // Der WAHRE Grund, getrennt nach Art - wer das Protokoll liest, soll bei
  // einer .jpg nicht nach einer Merkdatei suchen.
  const zeile = n.keinDok
    ? `[${zeit}] ${n.datei} | kein Dokument (${n.art}) - steht auf ` +
      `der Liste NICHTDOKUMENT im Baustein "Nur ein Bereich je Durchgang". ` +
      `Nicht gewandelt, nicht hochgeladen, nicht eingebettet, kein Eintrag im ` +
      `Katalog: Die Datei traegt keinen Fachinhalt, sie ist Beiwerk des ` +
      `Dateisystems oder die Buchhaltung dieser Anlage. Nach aussortiert/ ` +
      `verschoben (der Unterordner bleibt erhalten), damit der Eingang leer ` +
      `wird und sie nicht in jedem Durchgang erneut aufgegriffen wird. Wer sie ` +
      `zurueck will, legt sie aus aussortiert/ nach input/`
    : `[${zeit}] ${n.datei} | ${n.art} - aufgenommen werden nur ` +
      `${VORGESEHEN.join(', ')}. Bilder, Archive, CAD- und ` +
      `Messgeraetedateien liefern keinen belegbaren Text. Schon VOR der ` +
      `Sperre aus dem Eingang geraeumt, weil eine Charge aus lauter solchen ` +
      `Dateien sonst leer durch die Kette laeuft und die Sperre bis zum ` +
      `120-Minuten-Notnagel liegen bleibt. Soll das Format dazu, wird es in ` +
      `VORGESEHEN eingetragen; die Datei kommt mit demselben Schluessel zurueck`;
  const b = `mkdir -p "$(dirname ${dq(n.ziel)})" && mv -f ${dq(n.quelle)} ${dq(n.ziel)} && ` +
            `printf '%s\\n' ${dq(zeile)} >> ${dq(n.log)}`;
  // Mindestens einer geht immer durch - sonst bliebe bei einem sehr langen
  // Namen fuer immer alles liegen.
  const _byte = Buffer.byteLength(b, 'utf8');
  if (_befehle.length && _gezaehlt + _byte + 3 > HOECHSTENS_BYTE) break;
  _befehle.push(b);
  _gezaehlt += _byte + 3;
}
const aufraeumen = _befehle.join(' ; ');

if (aufraeumen) {
  if (echte) {
    // ⚠ Nur am ERSTEN Element. "Sperre setzen" steht auf executeOnce und
    //   liest genau dieses eine; den Befehl an alle zu haengen hiesse, ihn
    //   bis zu KI4KI_MENGE_JE_LAUF mal durch den Speicher zu tragen.
    raus[0] = { json: Object.assign({}, raus[0].json || {}, { aufraeumen: aufraeumen }),
                binary: raus[0].binary };
  } else {
    // ⭐ Im Eingang liegt NUR Abfall. Ohne ein Element hier bekaeme "Menge
    //   begrenzen" nichts, "Sperre setzen" liefe nicht, und der Abfall
    //   bliebe liegen - der gemeldete Zustand. Dieses eine Element traegt
    //   keine Datei, nur den Auftrag: "Sperre setzen" raeumt auf, meldet
    //   KI4KI-ABBRUCH und setzt KEINE Sperre; "Dateien zurueckholen" liest
    //   das Wort und beendet den Zweig still. Der naechste Durchgang findet
    //   einen sauberen Eingang vor.
    raus.push({ json: { nur_aufraeumen: true, aufraeumen: aufraeumen,
                        bereich: ersterBereich, nicht_dokumente: nichtdok.length } });
  }
}

// ⭐ DIE LISTEN REISEN MIT. "Code" liest sie ueber
//   $('Nur ein Bereich je Durchgang').first() - so steht die Positivliste
//   an genau EINER Stelle, und von "Code" geht sie als Text weiter an
//   "Ablage entscheiden", das sie fuer seine Begruendung braucht.
// ⚠ Nur am ERSTEN Element, wie schon der Wegraeum-Befehl: sie bis zu
//   KI4KI_MENGE_JE_LAUF mal durch den Speicher zu tragen waere unnoetig.
if (raus.length) {
  raus[0] = { json: Object.assign({}, raus[0].json || {},
                { vorgesehen: VORGESEHEN, korrespondenz_formate: KORRESPONDENZ }),
              binary: raus[0].binary };
}

console.log(`[Stand __STAND__] Bereich ${ersterBereich}: ${echte} zu verarbeiten, ` +
            `${schon} schon im Bestand, ${fremd} aus anderen Bereichen, ` +
            `${kein_dokument} keine Dokumente (alle Bereiche) - davon ` +
            `${_befehle.length} in diesem Durchgang nach ` +
            `aussortiert/ (${unvorgesehen} davon wegen unvorgesehener Endung), ` +
            `${ohne_ort} ohne input/ im Pfad liegen gelassen, ` +
            `${belegquellen} mitgelieferte PDF neben einem Office-Original ` +
            `(Belegquelle, nicht durch Docling).` +
            (echte ? '' : ' Nur Abfall im Eingang - dieser Durchgang raeumt nur auf.'));
return raus;

// ⚠ STILL AUSSTEIGEN, wenn "Sperre setzen" abgewinkt hat.
//   Der Baustein endet mit exit 0 statt exit 1 (ein normaler Zustand ist
//   kein Fehler). Ohne diese Wache liefe die Kette dann WEITER - und bei
//   belegter Sperre ein zweiter Durchgang parallel. Genau das soll die
//   Sperre verhindern. Eine leere Rueckgabe beendet den Zweig ohne
//   Fehlermeldung.
try {
  const _erste = $input.first();
  const _text = String((_erste && _erste.json && _erste.json.stdout) || '');
  if (_text.indexOf('KI4KI-ABBRUCH') !== -1) {
    console.log('[Sperre] ' + _text.trim());
    return [];
  }
} catch (e) {}

// Die Dateien nach der Sperre wieder einsetzen.
//
// "Sperre setzen" ist ein Befehls-Baustein. Er gibt NUR seine eigene
// Ausgabe zurueck ({exitCode, stdout: "Sperre gesetzt."}) und laesst die
// Binaerdaten der PDFs fallen. Ohne diesen Baustein ist danach der
// Dateiname weg: "Dateien klassifizieren" liest ihn aus
// item.binary.data.fileName, sieht "" und stuft jede Datei als
// "unsupported" ein.
//
// ⚠ GEHOLT WIRD AUS DEM FILTER, nicht aus dem Lade-Baustein. Die Sperre steht HINTER dem Filter, damit sie nur gesetzt wird,
//   wenn es wirklich neue Arbeit gibt. Wer hier wieder auf
//   'Daten vom Server laden' zeigt, holt die UNGEFILTERTE Liste zurueck -
//   dann waeren Dubletten und fremde Bereiche wieder drin.
//
// Kommt hier nichts an, ist das ein Fehler und keine leere Menge: Die
// Sperre wird nur gesetzt, wenn der Filter etwas uebrig gelassen hat.
// ⛔ GEHOLT WIRD AM ENDE DER VORKETTE, nicht in ihrer Mitte. Hier stand
//   $('Nur ein Bereich je Durchgang') - der Baustein VOR dem Mengen-Begrenzer.
//   Damit war "Menge begrenzen (Testlauf)" wirkungslos: Der Begrenzer schnitt
//   die Liste zu, und dieser Baustein holte die UNGESCHNITTENE zurueck. Ein
//   Eingang mit 6.395 Dateien lief dadurch als EIN Durchgang durch die ganze
//   Kette statt in Haeppchen zu je KI4KI_MENGE_JE_LAUF (Vorgabe 25).
// ⭐ WAS HIER ZURUECKKOMMT, SIND SEIT DEM 06.10. NUR NAMEN.
//   Die Dateien selbst liest "Daten vom Server laden" erst HINTER diesem
//   Baustein - und nur die Charge. Vorher stand der Lade-Baustein ganz
//   vorn und las JEDE Datei des Eingangs: 5.837 Dateien = 18 GB je
//   Durchgang, jede Minute, auf die Platte (binary-mode=filesystem). Das
//   hat 116,8 GB belegt, bis ENOSPC kam.
// ⛔ WER DEN LADE-BAUSTEIN WIEDER NACH VORN ZIEHT, baut genau diesen
//   Fehler nach. bau/ablauf_pruefen.py misst das (D1/D3).
const dateien = $('Menge begrenzen (Testlauf)').all();
if (!dateien.length) {
  throw new Error(
    'Nach der Sperre keine Dateien mehr da - die Kette ist unterbrochen.');
}
return dateien;

// Nur echte Dokumente gehen in den Upload.
//
// ⛔ Bis zum 24.09. lief JEDE Datei, die bis hierher kam, in den
//   Upload - die Positivliste (VORGESEHEN/KORRESPONDENZ) entschied erst
//   danach, in "Ablage entscheiden". Eine .msg, eine .jpg oder eine
//   Messgeraetedatei wurde also erst hochgeladen und eingebettet und
//   DANN aussortiert: Die Datei lag in aussortiert/, ihr Eintrag stand
//   weiter im Arbeitsbereich. Niemand raeumt ihn wieder weg.
//
// ⭐ Und die mitgelieferte PDF neben einem Office-Original (nur_beleg)
//   traegt den Schluessel des Originals. Wuerde sie hochgeladen, stuende
//   dasselbe Dokument zweimal unter demselben Namen im Katalog.
//
// ⚠ GEFILTERT WIRD NUR DER UPLOAD, nicht die Ablage:
//   "Ablage entscheiden" liest $('Code').all() und sieht deshalb auch
//   die hier aussortierten Elemente weiter. Wer stattdessen im Baustein
//   "Code" filtert, nimmt ihnen die Ablage mit - sie blieben in input/
//   liegen und wuerden jede Minute erneut aufgegriffen.
// ⛔ alwaysOutputData: true - UND ZWAR HIER, AN DIESEM BAUSTEIN (05.10.).
//   Dieser Filter ist die einzige Stelle, an der die Kette leer werden kann,
//   und "leer" heisst in n8n "der naechste Baustein wird nicht eingeplant"
//   (2.31.4, workflow-execute.js ~Z. 1242: bei executionOrder v1 ist die
//   einzige Bedingung outputData.length !== 0). Dann laeuft die Schleife
//   nicht an, "Ablage entscheiden" und "Sperre freigeben" werden NIE
//   erreicht - und es gibt keinen zweiten Weg dorthin. /files/json/.lauf.sperre
//   bliebe liegen, bis der 120-Minuten-Notnagel sie wegraeumt; danach dieselbe
//   Charge, derselbe Zustand. Alle zwei Stunden ein nutzloser Durchgang, auf
//   Dauer keine Aufnahme mehr - unbeaufsichtigt, und genau das ist der Fall,
//   fuer den die Anlage gebaut ist.
// ⛔ Das ist KEIN hypothetischer Fall: Korrespondenz (.msg/.eml) wird
//   bewusst nicht vor der Sperre weggeraeumt (Entscheidung 22.09.) und laeuft
//   bis hierher mit. Eine Charge aus lauter .msg - 65 Stueck im KAP-Bestand -
//   oder aus lauter textlosen PDFs macht diesen Filter leer, OHNE dass
//   irgendetwas kaputt ist. Dazu kommt der Riegel in "Code", wenn die
//   Positivliste nicht ankommt. Abschnitte 10 und 11 in bau/aufnahmetest.js
//   rechnen beide Faelle bis "Sperre freigeben" durch.
// ⚠ Was das Leer-Element auf dem Weg anrichtet, am Plan nachgelesen: die
//   Schleife dreht einmal mit leerem Text (ein billiger e2b-Aufruf),
//   "LLM Taggs" wirft bei itemMatching und reicht es per
//   continueRegularOutput weiter, "Markdown speichern" und "Upload Markdown
//   an AnythingLLM" scheitern ohne markdown_path und ohne Binaerfeld - es
//   wird also NICHTS hochgeladen -, "In Workspace einbetten" schickt
//   adds: [] los, und "Ablage entscheiden" liest ohnehin $('Code').all()
//   und sieht die echten Elemente. Ein Leerlauf, keine Aufnahme.
const _alle = $input.all();
const _raus = _alle.filter(e => e.json && e.json.hochladen !== false);
if (_raus.length !== _alle.length) {
  console.log('[Aufnahme] ' + (_alle.length - _raus.length) + ' von ' +
              _alle.length + ' Datei(en) nicht hochgeladen (Belegquelle, ' +
              'Korrespondenz, unvorgesehenes Format oder ohne Text) - ' +
              'sie werden trotzdem abgelegt.');
}
return _raus;
